    def __init__(self, data: torch.Tensor, attr):
        self.attr = attr

    @classmethod
    def __torch_function__(cls, func, types, args=(), kwargs=None):
        if kwargs is None:
            kwargs = {}

        return super().__torch_function__(func, types, args, kwargs)

class Model(Module):
    def __init__(self):
        super().__init__()
        self.param = BasevLLMParameter(torch.randn(10, 10), attr=1)

    def forward(self, x):
        return self.param * x

model = Model()
compiled_model = torch.compile(model, backend="eager", fullgraph=True)
compiled_model = model
x = torch.randn(10, 10)
print(compiled_model(x))
print(model.param.attr)
```

