        _checksums.append(torch.compile(checksum)(args[0]))
        return super().__torch_function__(func, types, args, kwargs)

    @classmethod
    def ignores_compile_internals(cls):
        return True

def g(x):
    return x.sin().cos()

torch.manual_seed(0)
x = torch.randn(3)
with CheckSumMode():
